<?php

declare(strict_types=1);

namespace Database\Factories;

use App\Enums\UserRole;
use App\Models\StaffInvitation;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * `token` is generated by the model's `creating` hook and `email` only has a
 * plain index (no unique constraint), so nothing here needs de-duplication.
 *
 * @extends Factory<StaffInvitation>
 */
class StaffInvitationFactory extends Factory
{
    /** @var class-string<StaffInvitation> */
    protected $model = StaffInvitation::class;

    /**
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'email' => $this->faker->unique()->safeEmail(),
            // Only admin/moderator may be granted through invitations.
            'role' => $this->faker->randomElement([UserRole::Moderator, UserRole::Admin]),
            'invited_by' => User::factory()->owner(),
            'expires_at' => now()->addDays(7),
            'accepted_at' => null,
        ];
    }

    public function forModerator(): static
    {
        return $this->state(fn (array $attributes): array => [
            'role' => UserRole::Moderator,
        ]);
    }

    public function forAdmin(): static
    {
        return $this->state(fn (array $attributes): array => [
            'role' => UserRole::Admin,
        ]);
    }

    public function invitedBy(?User $inviter = null): static
    {
        return $this->state(fn (array $attributes): array => [
            'invited_by' => $inviter?->getKey() ?? User::factory()->owner(),
        ]);
    }

    public function expired(): static
    {
        return $this->state(fn (array $attributes): array => [
            'expires_at' => now()->subDay(),
            'accepted_at' => null,
        ]);
    }

    public function accepted(): static
    {
        return $this->state(fn (array $attributes): array => [
            'expires_at' => now()->addDays(7),
            'accepted_at' => now(),
        ]);
    }
}
